diff --git a/src/global.css b/src/global.css
index 0ce4830..4665121 100644
--- a/src/global.css
+++ b/src/global.css
@@ -71,6 +71,175 @@
   --z-toast: 60;
 }

+/* ─────────────────────────────────────────────────────────────
+ * Tokens referenced across the app that had no definition — they
+ * were resolving to `unset`. Aliases, so they follow the theme.
+ * ───────────────────────────────────────────────────────────── */
+:root {
+  --color-accent: var(--color-vermilion);
+  --color-rule: var(--color-paper-3);
+  --color-crimson: var(--color-vermilion-2);
+}
+
+/* ─────────────────────────────────────────────────────────────
+ * Document colors — the text and highlight swatches in
+ * `palette.ts`, which named these custom properties without any
+ * of them ever being defined.
+ *
+ * Literal, and deliberately outside the theme blocks. These are
+ * colors the writer applies to their prose; they get written into
+ * the document as hex and have to render identically in an export
+ * that has no stylesheet. A theme may re-ink the room, never the
+ * manuscript.
+ * ───────────────────────────────────────────────────────────── */
+:root {
+  --color-text-olive: #556134;
+  --color-text-periwinkle: #454f9e;
+  --color-text-amber: #7a5a07;
+  --color-text-sienna: #964f40;
+  --color-highlight-butter: #fbeaa8;
+  --color-highlight-rose: #f8d3d4;
+  --color-highlight-sky: #cfe0f2;
+  --color-highlight-mint: #d5e6c4;
+  --color-highlight-lilac: #dcdff4;
+  --color-highlight-peach: #fadfd5;
+}
+
+/* ─────────────────────────────────────────────────────────────
+ * Texture tokens
+ *
+ * The letterpress surfaces — paper grain, foxing, the `.folio`
+ * emboss, `.ink-bleed`'s halo — used to hard-code `rgba(31,27,22,…)`
+ * ink and `rgba(255,255,255,…)` highlights. Baked that way they
+ * invert wrongly on any other ground: a white inset sheen on dark
+ * paper reads as a scratch. Expressed against the palette instead,
+ * every texture follows the active theme.
+ * ───────────────────────────────────────────────────────────── */
+:root {
+  /* Paper tooth. Its own tokens so a preset can flatten it entirely. */
+  --grain-1: color-mix(in srgb, var(--color-ink) 2.5%, transparent);
+  --grain-2: color-mix(in srgb, var(--color-ink) 2%, transparent);
+  --grain-3: color-mix(in srgb, var(--color-ink) 1.5%, transparent);
+  /* Base colors the textures are mixed from, never used at full strength. */
+  --emboss: #ffffff;
+  --foxing-base: #7a5426;
+  /*
+   * The color shadows are cast in. On paper this is just the ink, but a
+   * shadow always darkens — on a dark preset, mixing from ink would make
+   * every drop shadow glow. Kept separate so presets can say so.
+   */
+  --shade: var(--color-ink);
+}
+
+/* ─────────────────────────────────────────────────────────────
+ * Themes
+ *
+ * Each block redefines only the core palette; everything else is
+ * expressed against it, so a preset switch is one attribute flip
+ * on <html>. Writers may override the eight core tokens inline on
+ * top of any preset — see `src/utils/theme.ts`.
+ *
+ * `system` is resolved to a concrete preset by the bootstrap
+ * script before first paint, so no preset block is needed for it.
+ * ───────────────────────────────────────────────────────────── */
+
+/* Foolscap — cool grey-white, the yellow taken out. */
