metadata.preview:
  font-weight: 600;
  line-height: 1.6;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  transition: opacity 0.15s ease;
}
.manuscript-note-marker:hover {
  opacity: 0.7;
  text-decoration: underline;
}
.manuscript-note-text {
  flex: 1 1 auto;
}

/* Ink-bleed text effect for headings on hover */
.ink-bleed {
  transition: text-shadow 0.3s ease;
}

display.text:
  font-weight: 600;
  line-height: 1.6;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  transition: opacity 0.15s ease;
}
.manuscript-note-marker:hover {
  opacity: 0.7;
  text-decoration: underline;
}
.manuscript-note-text {
  flex: 1 1 auto;
}

/* Ink-bleed text effect for headings on hover */
.ink-bleed {
  transition: text-shadow 0.3s ease;
}
.ink-bleed:hover {
  animation: ink-bleed 0.3s ease forwards;
}

/* Department label — subtle underline grow on hover */
.dept-label {
  transition: letter-spacing 0.2s ease;
}
.dept-label:hover {
  letter-spacing: 0.22em;
}

/* Icon button — press-down feedback */
.icon-btn {
  transition:
    transform 0.1s ease,
    color 0.15s ease;
}
.icon-btn:active {
  transform: scale(0.92);
}

/* Smooth color transitions on interactive text */
button,
a {
  transition:
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease;
}

/* Zen masthead — collapses the header to a thin bar, fading out all
   chrome except the zen toggle. Fades back in on hover. */
.zen-masthead {
  transition:
    max-height 0.3s ease,
    opacity 0.3s ease;
  max-height: 24px;
  opacity: 0;
  overflow: hidden;
  border-bottom: none !important;
  pointer-events: auto;
}
.zen-masthead:hover {
  max-height: 80px;
  opacity: 1;
  border-bottom: 2px double var(--color-paper-3) !important;
}

/* Toast / status pulse — gentle attention without being aggressive */
@keyframes gentle-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}
.gentle-pulse {
  animation: gentle-pulse 2s ease-in-out infinite;
}

/* Dossier interview streaming: quiet state signal, not decorative motion. */
.interview-reasoning {
  border-radius: 3px;
}
.interview-stream-pulse {
  animation: gentle-pulse 1.25s ease-in-out infinite;
}

/* Reduced motion: disable all micro-interactions */
@media (prefers-reduced-motion: reduce) {
  .slide-in,
  .fade-in,
  .page-turn,
  .ink-bleed,
  .type-cursor::after,
  .twyne-endnote,
  .gentle-pulse,
  .interview-stream-pulse {
